import { componentAttrs } from "../_utils/component.helper";

function parseAssetUriParts(uri) {
  const match = /^matrix-asset:\/\/([a-zA-Z0-9.-]+)\/(\d+)(?::.+)?$/.exec(
    String(uri ?? ""),
  );
  return match ? { domain: match[1], id: match[2] } : null;
}

function settleResult(settled) {
  if (settled.status === "fulfilled") {
    return { ok: true, data: settled.value };
  }
  const reason = settled.reason;
  return { ok: false, error: reason?.message ?? String(reason) };
}

const ROOT_ID_PARAM_NAME = "rootId";

/**
 * CONTENT_API_URL is expected to be a Matrix REST resource URL -- auth is
 * configured on the REST resource itself, so this component never handles a
 * token. A literal "{assetId}" placeholder is substituted directly for
 * unusual shapes; otherwise the asset ID is appended as a `?rootId=` query
 * param, matching the same convention asset-children-picker's Asset Listing
 * feed uses -- the REST resource's own URL field reads it back out via a
 * `%globals_get_rootId%` keyword (requires "Append query string to the
 * request URL" enabled on the REST resource, confirmed via Squiz forums).
 */
function buildContentApiUrl(baseUrl, assetId) {
  if (!baseUrl) return null;
  if (baseUrl.includes("{assetId}")) {
    return baseUrl.replaceAll("{assetId}", encodeURIComponent(assetId));
  }
  return `${baseUrl}?${ROOT_ID_PARAM_NAME}=${encodeURIComponent(assetId)}`;
}

/**
 * Fetches an asset's children via a Matrix REST resource URL (configured
 * Matrix-side to call the Squiz Content API with its own auth) -- plain
 * unauthenticated fetch(), no token needed, same shape as
 * asset-children-picker's fetchAssetListingChildren().
 */
async function fetchContentApiChildren(assetId, baseUrl) {
  if (!baseUrl) {
    return {
      skipped: true,
      reason: "CONTENT_API_URL environment variable is not set.",
    };
  }

  if (!assetId) {
    return {
      skipped: true,
      reason:
        "No parentAsset selected, or its URI didn't parse into an asset ID.",
    };
  }

  const url = buildContentApiUrl(baseUrl, assetId);

  try {
    const res = await fetch(url);
    const text = await res.text();
    let body;
    try {
      body = JSON.parse(text);
    } catch {
      body = text.slice(0, 2000);
    }
    return { call: `GET ${url}`, status: res.status, ok: res.ok, body };
  } catch (err) {
    return {
      call: `GET ${url}`,
      ok: false,
      error: err?.message ?? String(err),
    };
  }
}

export default {
  async main(input = {}, info) {
    const { parentAsset = "" } = input;
    const { fns, env } = info;
    const contentApiUrl = env?.CONTENT_API_URL;
    const parts = parentAsset ? parseAssetUriParts(parentAsset) : null;

    const resolveUriPromise = parentAsset
      ? fns.resolveUri(parentAsset)
      : Promise.resolve({ skipped: true, reason: "No parentAsset selected." });

    const [resolveUriResult, childrenResult] = await Promise.allSettled([
      resolveUriPromise,
      fetchContentApiChildren(parts ? parts.id : null, contentApiUrl),
    ]);

    const display = {
      parentAsset: parentAsset || "(none)",
      contentApiUrl: contentApiUrl || "(CONTENT_API_URL not set)",
      parentAssetResolved: settleResult(resolveUriResult),
      children: settleResult(childrenResult),
    };

    return /*html*/ `<div ${componentAttrs("content-api-picker", input)}>
      <details open>
        <summary>Content API Picker</summary>
        <small>Component is configured for <code>CONTENT_API_URL</code> (optionally containing a literal <code>{assetId}</code> placeholder) -- point it at your Matrix REST resource's URL, which handles auth and returns JSON directly</small>
        <pre><code>${JSON.stringify(display, null, 2)}</code></pre>
      </details>
    </div>`;
  },
};
